 private Thread owner;private int count;private final boolean fair;public ReentrantLock(){this(false);}public ReentrantLock(boolean fair){this.fair=fair;}public boolean isFair(){return fair;}public int getHoldCount(){return isHeldByCurrentThread()?count:0;}public boolean isHeldByCurrentThread(){return owner==Thread.currentThread();}public boolean isLocked(){return owner!=null;}
